#include "d2u.h"
#include <stdio.h>
#include <string.h>
static const char*qname(uint32_t t){switch(t){case D2U_F32:return"F32";case D2U_F16:return"F16";case D2U_Q4_0:return"Q4_0";case D2U_Q5_0:return"Q5_0";case D2U_Q8_0:return"Q8_0";case D2U_Q2_K:return"Q2_K";case D2U_Q3_K:return"Q3_K";case D2U_Q4_K:return"Q4_K";case D2U_Q5_K:return"Q5_K";case D2U_Q6_K:return"Q6_K";case D2U_Q8_K:return"Q8_K";case D2U_BF16:return"BF16";default:return"OTHER";}}
int main(int ac,char**av){d2u_model m;char why[256];int rc,i;if(ac<2){fprintf(stderr,"usage: d2u_inspect shard1.gguf [shard2.gguf ...]\n");return 2;}rc=d2u_model_open(&m,ac-1,(const char**)&av[1]);if(rc){printf("OPEN=FAIL RC=%d\n",rc);return 3;}rc=d2u_validate_deepseek2(&m,why,sizeof(why));printf("VALIDATE=%s RC=%d\n",why,rc);printf("ARCH=%s NAME=%s SHARDS=%u TENSORS=%zu\n",m.cfg.architecture,m.cfg.name,m.shard_count,m.tensor_count);printf("BLOCKS=%u DENSE=%u MOE=%u HIDDEN=%u FF=%u\n",m.cfg.block_count,m.cfg.leading_dense_block_count,m.cfg.block_count-m.cfg.leading_dense_block_count,m.cfg.embedding_length,m.cfg.feed_forward_length);printf("EXPERTS=%u TOPK=%u SHARED=%u EXPERT_FF=%u GROUPS=%u/%u\n",m.cfg.expert_count,m.cfg.expert_used_count,m.cfg.expert_shared_count,m.cfg.expert_feed_forward_length,m.cfg.expert_group_used_count,m.cfg.expert_group_count);printf("MLA Q_LORA=%u KV_LORA=%u QK_NOPE=%u%s ROPE=%u V_HEAD=%u%s HEADS=%u\n",m.cfg.q_lora_rank,m.cfg.kv_lora_rank,m.cfg.qk_nope_head_dim,m.cfg.derived_qk_nope?"(derived)":"",m.cfg.rope_dimension_count,m.cfg.v_head_dim,m.cfg.derived_v_head?"(derived)":"",m.cfg.attention_head_count);printf("VOCAB=%u CONTEXT=%u\n",m.cfg.vocab_size,m.cfg.context_length);
 for(i=0;i<(int)m.tensor_count;i++){const d2u_tensor*t=&m.tensors[i];if(strstr(t->name,"ffn_gate_exps.weight")||strstr(t->name,"ffn_down_exps.weight")||strstr(t->name,"attn_k_b.weight")||strstr(t->name,"attn_v_b.weight"))printf("TENSOR %s TYPE=%s DIMS=%llu,%llu,%llu BYTES=%llu SHARD=%u OFF=%llu\n",t->name,qname(t->type),(unsigned long long)t->dims[0],(unsigned long long)t->dims[1],(unsigned long long)t->dims[2],(unsigned long long)t->size_bytes,t->shard,(unsigned long long)t->data_offset);}
 d2u_model_close(&m);return rc?4:0;}
